			var girderGeom = new THREE.BoxGeometry(8, 3, 8);
			var girderMat = new THREE.MeshPhongMaterial({ color: config.materialColors.metal });
			var girder = new THREE.Mesh(girderGeom, girderMat);
			girder.position.set(pos[0], 1.5, pos[2]);
			scene.add(girder);
