    var rockmaterial = new THREE.MeshStandardMaterial({ color: 0x3d3d3d, metalness: 0.1, roughness: 0.9 });
    var watersurfacematerial = new THREE.MeshStandardMaterial({ color: 0x1e3a5f, metalness: 0.7, roughness: 0.2 });

