  var colorTerrainBrown = 0x8B7355;
  var colorMilitarySand = 0xD4A574;
  var colorDarkMetal = 0x2F2F2F;
  var colorGreen = 0x4A7C2C;
  var colorDarkGreen = 0x2D5A1A;
