      var lightData = lights[j];
      if (lightData.frequency > 0) {
        var flicker = Math.abs(Math.sin(time * lightData.frequency * 3)) * 0.6 + 0.4;
        lightData.light.intensity = lightData.baseIntensity * flicker;
      }
