      var lineMat = new THREE.LineBasicMaterial({ color: 0x333355, linewidth: 3 });
      var sewerLine = new THREE.LineSegments(geom, lineMat);
      scene.add(sewerLine);
      sewerNetworks.push(sewerLine);
