      pointLight.position.set(pos.x, pos.y, pos.z);
      pointLight.castShadow = true;
      lightsGroup.add(pointLight);
      lights.push(pointLight);

      flickerLights.push({
        light: pointLight,
        baseIntensity: 1.5,
        time: Math.random() * 10
      });
