    var lights = buildEmergencyLighting();

    carrierGroup.add(hull);
    carrierGroup.add(deck);
    carrierGroup.add(planes);
    carrierGroup.add(hangars);
    carrierGroup.add(holes);
    carrierGroup.add(corals);
