    var ribbonGeom = new THREE.BoxGeometry(1.6, 0.15, 0.3);
    var ribbon = new THREE.Mesh(ribbonGeom, ribbonMat);
    ribbon.position.y = 0.15;
    group.add(ribbon);

    group.position.set(x, y, z);
