      var barrel = new THREE.Mesh(barrelGeom, materials.metal);
      barrel.position.set(-15 + i * 30, 12, 12);
      fireGroup.add(barrel);

      var flameGeom = new THREE.ConeGeometry(1.8, 4, 8);
      var flame = new THREE.Mesh(flameGeom, materials.fire);
