		// Crown finial sphere
		var crownGeom = new THREE.SphereGeometry(0.4, 8, 8);
		var crown = new THREE.Mesh(crownGeom, new THREE.MeshBasicMaterial({ color: 0xCCCCCC, emissive: 0x444444 }));
		crown.position.y = 2.8;
