    var box1Geometry = new THREE.BoxGeometry(1.5, 1.5, 8);
    var boxMaterial = new THREE.MeshStandardMaterial({ color: 0x8b4513, metalness: 0.3 });
    var box1 = new THREE.Mesh(box1Geometry, boxMaterial);
    box1.position.set(-3, 2, 0);
    box1.rotation.z = 0.3;
