    var valveMat = createMaterial(0xff6b35, 0x000000);

    var pipex = new THREE.BoxGeometry(25, 1, 1);
    var pipeXMesh = new THREE.Mesh(pipex, steelMat);
    pipeXMesh.position.set(0, 1, -18);
    scene.add(pipeXMesh);

