			var turretGeometry = new THREE.CylinderGeometry(8, 8, 6, 16);
			var turret = new THREE.Mesh(turretGeometry, gunmetalMaterial);
			turret.position.set(tankBody.position.x, tankBody.position.y + 10, tankBody.position.z);
			scene.add(turret);
