			var cannonGeometry = new THREE.CylinderGeometry(2, 2, 25, 8);
			var cannon = new THREE.Mesh(cannonGeometry, gunmetalMaterial);
			cannon.position.set(tankBody.position.x + 12, tankBody.position.y + 12, tankBody.position.z);
