			var trunk = new THREE.Mesh(trunkGeometry, trunkMaterial);
			trunk.position.set(Math.random() * 250 - 125, 12, Math.random() * 250 - 125);
			trunk.rotation.z = (Math.random() - 0.5) * 0.4;
			scene.add(trunk);
