			var poleGeom = new THREE.CylinderGeometry(1, 1, 6, 6);
			var poleMaterial = new THREE.MeshLambertMaterial({ color: 0x666666 });
			var pole = new THREE.Mesh(poleGeom, poleMaterial);
			pole.position.set(pos.x, 5, pos.z);
