			var base = new THREE.Mesh(new THREE.CylinderGeometry(3, 4, 2, 12), beaconBaseMaterial);
			base.position.set(pos[0], pos[1] - 10, pos[2]);
			base.castShadow = true;
			base.receiveShadow = true;
