		var greyMaterial = new THREE.MeshLambertMaterial({ color: 0x888888 });
		var darkGreyMaterial = new THREE.MeshLambertMaterial({ color: 0x555555 });

		var groundGeom = new THREE.BoxGeometry(400, 2, 400);
