    var towerGeometry = new THREE.CylinderGeometry(1.5, 2, 25, 16);
    var towerMaterial = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.6 });
    var tower = createObject(towerGeometry, towerMaterial, 0, 12.5, 0);
