    var basin = new THREE.Mesh(
      new THREE.CylinderGeometry(basinRadius, basinRadius, basinHeight, 24),
      new THREE.MeshStandardMaterial({ color: CONCRETE_GRAY, roughness: 0.7 })
    );
    basin.position.set(0, basinHeight / 2, 0);
    scene.add(basin);
    meshes.push(basin);

