    var debrisGeometry1 = new THREE.BoxGeometry(2, 0.5, 1);
    var debris1 = new THREE.Mesh(debrisGeometry1, hullMaterial);
    debris1.position.set(38, 1.2, -22);
    debris1.rotation.z = 0.8;
    debris1.castShadow = true;
