    battery.launchers = [];
    battery.radarDish = null;
    battery.commandBunker = null;
    battery.ammoDeps = [];
    battery.generators = [];
    battery.fenceSegments = [];
    battery.guardPosts = [];
    battery.logisticsTrucks = [];
    battery.sensorMasts = [];
    battery.camoNetting = [];
