    var tailMesh = new THREE.Mesh(tailCyl, tailMat);
    tailMesh.rotation.z = Math.PI / 2;
    tailMesh.position.set(0, 0, 3);
    tailMesh.castShadow = true;
    group.add(tailMesh);
    objects.push(tailMesh);

