    var floorMaterial = new THREE.MeshStandardMaterial({ color: 0xEEEEEE, roughness: 0.6, metalness: 0.2 });
    var floor = new THREE.Mesh(floorGeometry, floorMaterial);
    floor.position.y = -0.25;
