      var cleat = _cylinder(0.15, 0.15, 0.3, cleatMat);
      cleat.position.set(PIER_X + 4.2, 1.0, cz);
      _addObject(cleat);
      var cleat2 = _cylinder(0.15, 0.15, 0.3, cleatMat);
