    /* superstructure aft */
    var super2 = _box(2.5, 2.5, 2, superMat);
    super2.position.set(-4, 2.5, 0);
    grp.add(super2);

    /* gun mounts */
    var gunMat = _makeColor(0x888888);
    var gun1 = _cylinder(0.25, 0.25, 0.8, gunMat);
    gun1.position.set(7, 4, 1.2);
