    gun.position.set(0, 1.5, -1.5);
    gun.rotation.z = -Math.PI / 6;
    gun.castShadow = true;
    gun.receiveShadow = true;
    tank3.add(gun);

    scene.add(tank3);
    sceneObjects.push(tank3);
    tanks.push({
      group: tank3,
      stage: 3,
      position: tank3Z,
      speed: 0.1
    });
