    var truck2Matl = new THREE.MeshLambertMaterial({
      color: COLORS.militia
    });
    var truck2 = new THREE.Mesh(truck2Geom, truck2Matl);
    truck2.position.set(0, 3, -80);
    truck2.castShadow = true;
    truckGroup.add(truck2);
    meshes.push(truck2);

    return truckGroup;
