    canopy.rotation.z = Math.random() * 0.1;

    // Support poles
    var poleGeo = new THREE.CylinderGeometry(0.3, 0.3, height, 8);
    createMesh(poleGeo, colors.shadowDark, x - width/2 + 1, y + height/2, z - width/2 + 1);
    createMesh(poleGeo, colors.shadowDark, x + width/2 - 1, y + height/2, z - width/2 + 1);
    createMesh(poleGeo, colors.shadowDark, x - width/2 + 1, y + height/2, z + width/2 - 1);
    createMesh(poleGeo, colors.shadowDark, x + width/2 - 1, y + height/2, z + width/2 - 1);

