  var FLIGHT_DECK_Y           = 12;
  var ISLAND_WIDTH            = 15;
  var ISLAND_HEIGHT           = 35;
  var ISLAND_DEPTH            = 12;
  var JET_LENGTH              = 18;
  var JET_HEIGHT              = 5;
  var JET_WING_SPAN           = 12;
  var CATAPULT_COUNT          = 2;
  var CATAPULT_LENGTH         = 90;
  var CATAPULT_WIDTH          = 3.5;
  var ARRESTING_WIRE_COUNT    = 4;
