  var HANGAR_ACCESS_X         = -20;
  var AA_GUN_COUNT            = 6;
  var RADAR_HEIGHT            = 8;
  var ELEVATOR_CYCLE_TIME     = 4.0;
  var CATAPULT_PULSE_RATE     = 2.5;
  var LANDING_LIGHT_BLINK     = 0.8;
  var DECK_CREW_LIGHT_BLINK   = 1.2;
  var RADAR_ROTATE_SPEED      = 0.8;

  /* ── state ─────────────────────────────────────────────────────────────── */
  var _scene           = null;
  var _camera          = null;
