    _catapults = [];
    _arrestingWires = [];
    _aaGuns = [];
    _parkedJets = [];
    _landingLights = [];
    _deckCrewLights = [];
    _jetBlastDeflectors = [];

    /* reset timers */
    _elevatorTimer = 0;
    _catapultTimer = 0;
    _landingLightTimer = 0;
    _deckCrewLightTimer = 0;
    _radarRotation = 0;

