      var barrierMat = new THREE.MeshPhongMaterial({ color: 0xFFFF00 });
      var barrier = new THREE.Mesh(barrierGeom, barrierMat);
      barrier.position.set(positions[i].x, 1, positions[i].z);
      barrier.castShadow = true;
      group.add(barrier);
