    state.throne.position.set(0, 1.5, 25);
    state.scene.add(state.throne);

    // Throne backrest
    var backGeo = new THREE.BoxGeometry(4, 5, 0.5);
    var back = new THREE.Mesh(backGeo, goldMat);
    back.position.set(0, 4, 23);
